// ProfileTab.js
import {
  Box,
  Typography,
  TextField,
  Button,
  IconButton,
  InputAdornment,
  Paper,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Grid,
  Snackbar,
  Alert,
  CircularProgress,
  FormControl,
  FormHelperText
} from '@mui/material';
import { Visibility, VisibilityOff } from '@mui/icons-material';
import { useAuth } from './AuthContext';
import { useEffect, useState } from 'react';

const ProfileTab = () => {
  const { user } = useAuth();
  const [newUsername, setNewUsername] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordConfirm, setPasswordConfirm] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [lastUpdated, setLastUpdated] = useState({ username: null, password: null });
  const [passwordError, setPasswordError] = useState('');
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

  const [openConfirmUsername, setOpenConfirmUsername] = useState(false);
  const [openConfirmPassword, setOpenConfirmPassword] = useState(false);

  useEffect(() => {
    fetchLastUpdated();
  }, []);

  const fetchLastUpdated = () => {
    try {
      const storedData = localStorage.getItem(`lastUpdated_${user?.workerID}`);
      if (storedData) {
        setLastUpdated(JSON.parse(storedData));
      }
    } catch (error) {
      console.error('Error fetching last updated information:', error);
    }
  };

  const canUpdateToday = (field) => {
    if (!lastUpdated[field]) return true;

    const lastDate = new Date(lastUpdated[field]);
    const today = new Date();
    lastDate.setHours(0, 0, 0, 0);
    today.setHours(0, 0, 0, 0);
    return lastDate.getTime() !== today.getTime();
  };

  const togglePasswordVisibility = () => {
    setShowPassword((prev) => !prev);
  };

  const handleUsernameChange = (e) => setNewUsername(e.target.value);
  const handlePasswordChange = (e) => setNewPassword(e.target.value);
  const handleConfirmPasswordChange = (e) => setConfirmPassword(e.target.value);
  const handleConfirmPasswordInput = (e) => {
    setPasswordConfirm(e.target.value);
    setPasswordError('');
  };

  const showSnackbarMessage = (message, severity = 'success') => {
    setSnackbar({ open: true, message, severity });
  };

  const handleOpenUsernameDialog = () => {
    if (!newUsername) return showSnackbarMessage('Please enter a new username', 'error');
    if (!canUpdateToday('username')) return showSnackbarMessage('You can only change your username once per day', 'warning');

    setPasswordConfirm('');
    setPasswordError('');
    setOpenConfirmUsername(true);
  };

  const handleOpenPasswordDialog = () => {
    if (!newPassword) return showSnackbarMessage('Please enter a new password', 'error');
    if (newPassword !== confirmPassword) return showSnackbarMessage('Passwords do not match', 'error');
    if (!canUpdateToday('password')) return showSnackbarMessage('You can only change your password once per day', 'warning');

    setPasswordConfirm('');
    setPasswordError('');
    setOpenConfirmPassword(true);
  };

  const verifyPassword = async () => {
    if (!passwordConfirm) {
      setPasswordError('Please enter your password');
      return false;
    }

    try {
      const response = await fetch('http://localhost:8080/worker/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: user.username, password: passwordConfirm }),
      });

      if (response.ok) return true;
      setPasswordError('Incorrect password');
      return false;
    } catch (error) {
      console.error('Error verifying password:', error);
      setPasswordError('Error verifying password');
      return false;
    }
  };

  const confirmUsernameUpdate = async () => {
    if (!user?.workerID) return showSnackbarMessage('User information is missing', 'error');
    if (!await verifyPassword()) return;

    setIsUpdating(true);

    try {
      const response = await fetch(`http://localhost:8080/worker/${user.workerID}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...user, username: newUsername }),
      });

      if (response.ok) {
        const updatedUser = { ...user, username: newUsername };
        localStorage.setItem('user', JSON.stringify(updatedUser));
        localStorage.setItem('username', newUsername);
        const updatedTimestamps = { ...lastUpdated, username: new Date().toISOString() };
        localStorage.setItem(`lastUpdated_${user.workerID}`, JSON.stringify(updatedTimestamps));
        setLastUpdated(updatedTimestamps);
        setNewUsername('');
        showSnackbarMessage('Username updated successfully!');
      } else {
        showSnackbarMessage('Failed to update username', 'error');
      }
    } catch (err) {
      showSnackbarMessage('Error updating username: ' + err.message, 'error');
    } finally {
      setIsUpdating(false);
      setOpenConfirmUsername(false);
    }
  };

  const confirmPasswordUpdate = async () => {
    if (!user?.workerID) return showSnackbarMessage('User information is missing', 'error');
    if (!await verifyPassword()) return;

    setIsUpdating(true);

    try {
      const response = await fetch(`http://localhost:8080/worker/${user.workerID}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...user, password: newPassword }),
      });

      if (response.ok) {
        const updatedTimestamps = { ...lastUpdated, password: new Date().toISOString() };
        localStorage.setItem(`lastUpdated_${user.workerID}`, JSON.stringify(updatedTimestamps));
        setLastUpdated(updatedTimestamps);
        setNewPassword('');
        setConfirmPassword('');
        showSnackbarMessage('Password updated successfully!');
      } else {
        showSnackbarMessage('Failed to update password', 'error');
      }
    } catch (err) {
      showSnackbarMessage('Error updating password: ' + err.message, 'error');
    } finally {
      setIsUpdating(false);
      setOpenConfirmPassword(false);
    }
  };

  const handleCloseSnackbar = () => setSnackbar({ ...snackbar, open: false });

  if (!user) {
    return <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '70vh' }}><CircularProgress /></Box>;
  }

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ fontWeight: 'bold', textAlign: 'center', mb: 4 }}>User Profile</Typography>
      <Paper elevation={3} sx={{ p: 4, maxWidth: 600, mx: 'auto' }}>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Typography variant="h5" sx={{ mb: 2, textAlign: 'center' }}>{user.firstName} {user.lastName}</Typography>
            <Typography variant="subtitle1" sx={{ mb: 2, textAlign: 'center', color: 'text.secondary' }}>
              {user.admin ? 'Administrator' : 'Inspector'}
            </Typography>
          </Grid>

          <Grid item xs={12}>
            <Typography variant="h6">Username</Typography>
            <Typography variant="body1" sx={{ mb: 2 }}>
              Current: <strong>{user.username}</strong>
            </Typography>
            <Box sx={{ display: 'flex', gap: 2 }}>
              <TextField
                fullWidth label="New Username" value={newUsername} onChange={handleUsernameChange}
                variant="outlined" helperText="You can only change your username once per day"
              />
              <Button variant="contained" onClick={handleOpenUsernameDialog} disabled={!newUsername || isUpdating} sx={{ mt: 1 }}>
                Change
              </Button>
            </Box>
          </Grid>

          <Grid item xs={12} sx={{ mt: 2 }}>
            <Typography variant="h6">Password</Typography>
            <Typography variant="body1" sx={{ mb: 2 }}>Change your current password</Typography>
            <TextField
              fullWidth label="New Password" type={showPassword ? 'text' : 'password'}
              value={newPassword} onChange={handlePasswordChange} margin="normal" variant="outlined"
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton onClick={togglePasswordVisibility} edge="end">
                      {showPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                )
              }}
            />
            <TextField
              fullWidth label="Confirm Password" type={showPassword ? 'text' : 'password'}
              value={confirmPassword} onChange={handleConfirmPasswordChange}
              margin="normal" variant="outlined"
            />
            <Button variant="contained" onClick={handleOpenPasswordDialog} disabled={!newPassword || !confirmPassword || isUpdating}>
              Change Password
            </Button>
          </Grid>
        </Grid>
      </Paper>

      {/* Username Confirm Dialog */}
      <Dialog open={openConfirmUsername} onClose={() => setOpenConfirmUsername(false)}>
        <DialogTitle>Confirm Username Change</DialogTitle>
        <DialogContent>
          <FormControl fullWidth error={!!passwordError}>
            <TextField label="Enter current password" type="password" value={passwordConfirm} onChange={handleConfirmPasswordInput} />
            {passwordError && <FormHelperText>{passwordError}</FormHelperText>}
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenConfirmUsername(false)} color="primary">Cancel</Button>
          <Button onClick={confirmUsernameUpdate} color="primary" autoFocus>Confirm</Button>
        </DialogActions>
      </Dialog>

      {/* Password Confirm Dialog */}
      <Dialog open={openConfirmPassword} onClose={() => setOpenConfirmPassword(false)}>
        <DialogTitle>Confirm Password Change</DialogTitle>
        <DialogContent>
          <FormControl fullWidth error={!!passwordError}>
            <TextField label="Enter current password" type="password" value={passwordConfirm} onChange={handleConfirmPasswordInput} />
            {passwordError && <FormHelperText>{passwordError}</FormHelperText>}
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenConfirmPassword(false)} color="primary">Cancel</Button>
          <Button onClick={confirmPasswordUpdate} color="primary" autoFocus>Confirm</Button>
        </DialogActions>
      </Dialog>

      <Snackbar open={snackbar.open} autoHideDuration={6000} onClose={handleCloseSnackbar}>
        <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default ProfileTab;
